import { useState } from 'react';
import type {
  ArtifactRef,
  InteractionSnapshot,
  NavigationTarget,
  ProcessClient,
} from '@wright/process-client';
import {
  ProcessUI,
  ProgressPanel,
  ReasonNotice,
  ResultCard,
  Section,
  WorkingControls,
} from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

const baselineRoles = new Set([
  'baseline_40_geometry',
  'baseline_40_coarse',
  'baseline_40_fine',
]);
const revisionRoles = new Set([
  'revision_60_geometry',
  'revision_60_coarse',
  'revision_60_fine',
]);

export default function App({ client, snapshot, readOnly }: AppProps) {
  const [navigationError, setNavigationError] = useState(false);
  const outputs = snapshot.outputs ?? [];
  const baseline = outputs.filter(output => baselineRoles.has(output.role));
  const revision = outputs.filter(output => revisionRoles.has(output.role));
  const shared = outputs.filter(output =>
    !baselineRoles.has(output.role) && !revisionRoles.has(output.role));

  const navigate = (target: NavigationTarget) => {
    setNavigationError(false);
    void client.navigate(target).catch(() => setNavigationError(true));
  };
  const openEvidence = (reference: ArtifactRef) => navigate({
    kind: 'evidence',
    artifact_ref: reference.artifact_ref,
    result_id: reference.result_id,
  });
  const renderResult = (output: (typeof outputs)[number]) => (
    <ResultCard key={output.result_id} output={output}
      onNavigate={navigate} onOpen={openEvidence} />
  );

  return <ProcessUI>
    <Section title="Heat-spreader candidate comparison">
      {readOnly && <p>Preview — this presentation is read-only.</p>}
      <ProgressPanel state={snapshot.state}
        observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
      <button type="button" onClick={() => navigate({ kind: 'process' })}>
        Open process
      </button>
      {navigationError && <p role="alert">
        Wright could not open that destination. Use the working view to
        reconcile the current process and inspect the exact recorded result.
      </p>}
    </Section>

    <Section title="Inputs, readiness, and review controls">
      <p>Existing process files are explicitly defaulted; replace them if needed
        before checking readiness.</p>
      <WorkingControls client={client} snapshot={snapshot} readOnly={readOnly}
        onNavigate={navigate} />
    </Section>

    <Section title="Candidate results">
      {outputs.length === 0 &&
        <p>No process results are available in this snapshot.</p>}
      <table>
        <caption>Recorded results grouped by candidate role</caption>
        <thead><tr><th scope="col">Baseline 40</th>
          <th scope="col">Revision 60</th></tr></thead>
        <tbody><tr><td>{baseline.map(renderResult)}</td>
          <td>{revision.map(renderResult)}</td></tr></tbody>
      </table>
      {shared.length > 0 && <section aria-labelledby="shared-results">
        <h3 id="shared-results">Shared evidence and checks</h3>
        {shared.map(renderResult)}
      </section>}
    </Section>

    <Section title="Engineering limitations">
      <p>Result availability, artifact validity, previews, and compliance are
        separate. A saved decision is evidence, not fresh permission.</p>
      <p>No artifact-specific viewer is declared. Use each exact result or
        evidence link for supported inspection. Missing or stale observations
        remain unavailable or stale until the authoritative snapshot says otherwise.</p>
    </Section>
  </ProcessUI>;
}
